create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, slug text unique not null, display_name text, bio text, avatar_url text, links jsonb not null default '[]'::jsonb, theme jsonb not null default '{}'::jsonb, created_at timestamptz default now(), updated_at timestamptz default now());\nalter table public.profiles enable row level security;\ncreate policy "profiles are public read" on public.profiles for select using (true);\ncreate policy "owners insert profile" on public.profiles for insert with check (auth.uid()=id);\ncreate policy "owners update profile" on public.profiles for update using (auth.uid()=id) with check (auth.uid()=id);\ncreate policy "owners delete profile" on public.profiles for delete using (auth.uid()=id);\ncreate table if not exists public.click_events (id bigint generated always as identity primary key, profile_id uuid references public.profiles(id) on delete cascade, link_url text, created_at timestamptz default now());\nalter table public.click_events enable row level security;\ncreate policy "owners see clicks" on public.click_events for select using (auth.uid()=profile_id);\n